#include "process_private.h" 
/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/
static Timeout_Q_Status launch_delayed( Process_Node *new );
/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

/*--------------------------------------------------------------------------*/

void process_launch( Process_Node *new , UInt32 delay_ms )
{
    if( delay_ms )
    {
        timeout_q_remove( (void *)new ) ;

        timeout_q_insert( (Timeout_Q_Func)launch_delayed , (Timeout_Q_Arg)new , delay_ms/10 , 1 , 1 );
    }
    else
    {
        PER_EXEC_ATOMIC( process_looping_start( new ) );
    }
}

/*--------------------------------------------------------------------------*/

Timeout_Q_Status launch_delayed( Process_Node *new )
{
    PER_EXEC_ATOMIC( process_looping_start( new ) );
    
    return TIMEOUT_Q_COMPLETE ; 
}

